type serviceBaseEndpointConfig map[string]string

func (c serviceBaseEndpointConfig) GetServiceBaseEndpoint(ctx context.Context, sdkID string) (string, bool, error) {
	endpoint, ok := c[sdkID]
	return endpoint, ok && endpoint != "", nil
}

func configuredServiceBaseEndpoints(c *Config) serviceBaseEndpointConfig {
	endpoints := serviceBaseEndpointConfig{}

	if c.IamEndpoint != "" {
		endpoints[iam.ServiceID] = c.IamEndpoint
	}
	if c.SsoEndpoint != "" {
		endpoints[sso.ServiceID] = c.SsoEndpoint
	}
	if c.StsEndpoint != "" {
		endpoints[sts.ServiceID] = c.StsEndpoint
	}

	return endpoints
}

func applyServiceBaseEndpointConfig(awsConfig *aws.Config, c *Config) {
	endpoints := configuredServiceBaseEndpoints(c)
	if len(endpoints) == 0 {
		return
	}

	awsConfig.ConfigSources = append([]interface{}{endpoints}, awsConfig.ConfigSources...)
}

func setServiceEndpointEnv(c *Config) func() {
	overrides := map[string]string{
		"AWS_ENDPOINT_URL_IAM": c.IamEndpoint,
		"AWS_ENDPOINT_URL_SSO": c.SsoEndpoint,
		"AWS_ENDPOINT_URL_STS": c.StsEndpoint,
	}

	previousValues := make(map[string]string, len(overrides))
	previouslySet := make(map[string]bool, len(overrides))

	for name, value := range overrides {
		if value == "" {
			continue
		}

		previousValues[name], previouslySet[name] = os.LookupEnv(name)
		os.Setenv(name, value)
	}

	return func() {
		for name := range previousValues {
			if previouslySet[name] {
				os.Setenv(name, previousValues[name])
			} else {
				os.Unsetenv(name)
			}
		}
	}
}
